export type Format = { id: string; label: string }
export type Product = {
  id: string; name: string; brand: string; summary: string; image: string;
  imageNote?: string; formats: Format[]; price: string; period: string; source: string;
}
// A deliberately small, source-reviewed trial. No automatic matches or live prices.
export const products: Product[] = [
  {
    id: 'pan-bauletto-bianco-400g', name: 'Pan Bauletto bianco', brand: 'Mulino Bianco',
    summary: 'Bianco · 400 g', image: 'data:image/jpeg;base64,',
    formats: [{ id: '400g', label: '400 g' }], price: '0,89 €', period: '7-20 ottobre',
    source: 'https://fsxctxzzifohmbgqwcxk.supabase.co/storage/v1/object/public/volantini/EKOMPromo21-LGPM_p6.jpg',
  },
  {
    id: 'domopak-sacchetti-gelo', name: 'Sacchetti gelo', brand: 'Domo Pak',
    summary: '3 formati', image: 'data:image/jpeg;base64,', imageNote: 'La foto mostra il formato medio da 20 pezzi.',
    formats: [{ id: 'piccoli-30', label: 'Piccoli · 30 pezzi' }, { id: 'medi-20', label: 'Medi · 20 pezzi' }, { id: 'grandi-15', label: 'Grandi · 15 pezzi' }],
    price: '0,79 €', period: '9-22 settembre',
    source: 'https://fsxctxzzifohmbgqwcxk.supabase.co/storage/v1/object/public/volantini/EKOMPromo19-LGPM_p5.jpg',
  },
]
export type Saved = { productId: string; formatId: string }
export const STORAGE_KEY = 'mioprodotto.trial.watchlist.v1'
export function same(a: Saved, b: Saved) { return a.productId === b.productId && a.formatId === b.formatId }
export function readSaved(raw: string | null): Saved[] {
  if (!raw) return []
  const value: unknown = JSON.parse(raw)
  if (!Array.isArray(value)) throw new Error('Invalid saved list')
  const clean: Saved[] = []
  for (const item of value) {
    if (!item || typeof item !== 'object') continue
    const candidate = item as Saved
    const product = products.find(p => p.id === candidate.productId)
    if (product?.formats.some(f => f.id === candidate.formatId) && !clean.some(x => same(x, candidate))) {
      clean.push({ productId: candidate.productId, formatId: candidate.formatId })
    }
  }
  return clean
}
